	go func(id int) {
		defer wg.Done()
		for job := range jobs {
			// Simulate some work
			time.Sleep(time.Millisecond)

			atomic.AddInt32(&processedCount, 1)

			// BUG 2: Potential Deadlock if buffer fills -> FIXED by concurrent reader
			results <- Result{JobID: job.ID, Val: job.ID * 2}
		}
	}(i)
}

// Send jobs
go func() {
	for i := 0; i < numJobs; i++ {
		jobs <- Job{ID: i}
	}
	close(jobs)
